# ============================================================
# 测试用例生成器
# ============================================================

def get_chapters(count: int = 5) -> dict:
    """
    生成多个测试 chapter.

    Returns:
        Dict mapping chapter_id to content
    """
    chapters = {
        "chapter_1": SHORT_CHAPTER,
        "chapter_2": MEDIUM_CHAPTER,
        "chapter_3": LONG_CHAPTER,
        "front_matter": FRONT_MATTER,
        "back_matter": BACK_MATTER,
    }

    # 如果需要更多，复制并编号
    if count > 5:
        for i in range(6, count + 1):
            chapters[f"chapter_{i}"] = MEDIUM_CHAPTER.replace("第二章", f"第{i}章")

    return chapters


def get_japanese_chapters(count: int = 3) -> dict:
    """生成日文测试 chapter."""
    return {
        "chapter_1": SHORT_CHAPTER_JP,
        "chapter_2": MEDIUM_CHAPTER_JP,
        "chapter_3": MEDIUM_CHAPTER_JP.replace("第二章", "第三章"),
    }
